BEGIN;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
DO $payload$
DECLARE payload jsonb; data jsonb; started timestamptz:=clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0))
    OR NOT EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-04b0acb423d0e2d372e384c1eb3d' AND status='running' AND operation_hash='04b0acb423d0e2d372e384c1eb3d34d2526fc7587037ead7d4b520e02bc8c673' AND deadline_at>clock_timestamp()) THEN RAISE EXCEPTION 'ce200_lease'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) INTO data FROM (SELECT category_id,category_name,count(*)::int AS n,
      count(*) FILTER (WHERE (published IS TRUE AND (display_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)' OR category_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)')))::int AS frame_n,
      md5(string_agg(id||':'||md5(to_jsonb(p)::text),',' ORDER BY id COLLATE "C") FILTER (WHERE (published IS TRUE AND (display_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)' OR category_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)')))) AS frame_hash
      FROM public.carrefour_products p WHERE published IS TRUE
      GROUP BY category_id,category_name ORDER BY category_id::text,category_name LIMIT 500) q;
  payload:=jsonb_build_object('job_key','ce1-ce200-04b0acb423d0e2d372e384c1eb3d','operation_hash','04b0acb423d0e2d372e384c1eb3d34d2526fc7587037ead7d4b520e02bc8c673',
    'project_ref','gkffvigcnsesbaihycay','captured_at',started,'kind','census','store','carrefour',
    'cursor','','rows',data,'row_count',jsonb_array_length(data),'elapsed_ms',extract(epoch FROM clock_timestamp()-started)*1000);
  IF jsonb_array_length(data)>500 OR octet_length(payload::text)>122880 THEN RAISE EXCEPTION 'ce200_result_limit'; END IF;
  UPDATE comparator_strict.execution_jobs SET status='succeeded',finished_at=clock_timestamp(),
    receipt=jsonb_build_object('payload_sha256',encode(sha256(convert_to(payload::text,'UTF8')),'hex'),'row_count',jsonb_array_length(data),'payload_bytes',octet_length(payload::text),'elapsed_ms',payload->'elapsed_ms') WHERE job_key='ce1-ce200-04b0acb423d0e2d372e384c1eb3d';
